package com.lordescanor.botforge;
import java.io.*; import java.util.zip.*;
public class ZipUtils { public static void unzip(InputStream in,File out)throws IOException{byte[] b=new byte[8192];ZipInputStream z=new ZipInputStream(new BufferedInputStream(in));ZipEntry e;while((e=z.getNextEntry())!=null){File f=new File(out,e.getName());if(e.isDirectory()){f.mkdirs();continue;}File parent=f.getParentFile();if(parent!=null)parent.mkdirs();try(FileOutputStream o=new FileOutputStream(f)){int n;while((n=z.read(b))>0)o.write(b,0,n);}}z.close();} public static void zip(File dir,File out)throws IOException{try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(out))){zipDir(dir,dir,z);}}private static void zipDir(File root,File cur,ZipOutputStream z)throws IOException{File[] fs=cur.listFiles();if(fs==null)return;byte[] b=new byte[8192];for(File f:fs){String n=root.toURI().relativize(f.toURI()).getPath();if(f.isDirectory())zipDir(root,f,z);else{z.putNextEntry(new ZipEntry(n));try(FileInputStream in=new FileInputStream(f)){int k;while((k=in.read(b))>0)z.write(b,0,k);}z.closeEntry();}}}}
